import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Input, Select } from 'antd';
import cn from 'classnames';

import { REPORT_STATUS_OPTIONS } from 'entities/Report';
import { EFilters } from 'features/Filters/model/enums';

import { OPTIONS_MAX_HEIGHT_EXTENDED, OPTIONS_MAX_HEIGHT_MAIN } from '../../consts';
import { useOffersSelect } from '../../hooks/useOffersSelect';
import { useStateFilters } from '../../hooks/useStateFilters';
import { ExtendedFiltersSection } from '../ExtendedFiltersSection/ExtendedFiltersSection';
import { ExtendedFiltersWrapper } from '../ExtendedFiltersWrapper/ExtendedFiltersWrapper';

import styles from './ReportsExtendedFilters.module.scss';

interface IReportsExtendedFiltersProps extends HTMLAttributes<HTMLDivElement> {
	appliedFiltersCount: number;
}

export const ReportsExtendedFilters: FC<IReportsExtendedFiltersProps> = ({
	className,
	appliedFiltersCount,
	...props
}) => {
	const { t } = useTranslation();
	const { applyFilters, clearFilters, getALLFilterValues, onFilterChange, setInitFiltersFilters } =
		useStateFilters(true);
	const { isFetching, isLoading, offersOptions, setSearchValue } = useOffersSelect();

	return (
		<ExtendedFiltersWrapper
			applyFilters={applyFilters}
			appliedFiltersCount={appliedFiltersCount}
			clearFilters={clearFilters}
			modalProps={{ width: 760 }}
			onOpen={setInitFiltersFilters}>
			<div {...props} className={cn(className, styles.extendedFilters)}>
				<div className={styles.extendedFilters__col}>
					<ExtendedFiltersSection title={t('Status')}>
						<Select
							onChange={(value) => onFilterChange(EFilters.STATUS, value)}
							value={getALLFilterValues(EFilters.STATUS)}
							options={REPORT_STATUS_OPTIONS}
							placeholder={t('Status')}
							size="large"
							mode="multiple"
							listHeight={OPTIONS_MAX_HEIGHT_EXTENDED}
							allowClear
						/>
					</ExtendedFiltersSection>
				</div>

				<div className={styles.extendedFilters__col}>
					<ExtendedFiltersSection title={t('Offers')}>
						<Select
							mode="multiple"
							value={getALLFilterValues(EFilters.OFFER_ID)}
							options={offersOptions}
							onChange={(value) => {
								setSearchValue('');
								onFilterChange(EFilters.OFFER_ID, Array.isArray(value) ? value : [value]);
							}}
							onSearch={setSearchValue}
							showSearch
							filterOption={false}
							optionFilterProp="label"
							allowClear
							disabled={isLoading}
							listHeight={OPTIONS_MAX_HEIGHT_MAIN}
							loading={isLoading || isFetching}
							placeholder={t('Offer name')}
							size="large"
						/>
					</ExtendedFiltersSection>

					<ExtendedFiltersSection title={t('Amount')}>
						<div className={styles.extendedFilters__inline}>
							<Input
								onChange={(e) => onFilterChange(EFilters.CAP_AMOUNT_FROM, e.target.value)}
								value={getALLFilterValues(EFilters.CAP_AMOUNT_FROM) || ''}
								placeholder={t('From')}
								size="large"
								type="number"
								allowClear
							/>
							<Input
								onChange={(e) => onFilterChange(EFilters.CAP_AMOUNT_TO, e.target.value)}
								value={getALLFilterValues(EFilters.CAP_AMOUNT_TO) || ''}
								placeholder={t('Up to')}
								size="large"
								type="number"
								allowClear
							/>
						</div>
					</ExtendedFiltersSection>
				</div>
			</div>
		</ExtendedFiltersWrapper>
	);
};
