import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Select } from 'antd';
import cn from 'classnames';

import { REPORT_STATUS_OPTIONS } from 'entities/Report';

import { OPTIONS_MAX_HEIGHT_MAIN } from '../../consts';
import { useFilters } from '../../hooks/useFilters';
import { EFilters } from '../../model/enums';
import { ReportsExtendedFilters } from '../ReportsExtendedFilters/ReportsExtendedFilters';

import styles from './ReportsMainFilters.module.scss';

interface IReportsMainFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsMainFilters: FC<IReportsMainFiltersProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	const { getALLFilterValues, getFiltersCount, onFilterChange } = useFilters(true);

	return (
		<div {...props} className={cn(className, styles.mainFilters)}>
			<Select
				className={styles.select}
				onChange={(value) => onFilterChange(EFilters.STATUS, value)}
				value={getALLFilterValues(EFilters.STATUS)}
				options={REPORT_STATUS_OPTIONS}
				placeholder={t('Status')}
				size="large"
				mode="multiple"
				showSearch
				listHeight={OPTIONS_MAX_HEIGHT_MAIN}
				allowClear
				maxTagCount={'responsive'}
			/>

			<ReportsExtendedFilters appliedFiltersCount={getFiltersCount()} />
		</div>
	);
};
