import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { NavLink, useLocation, useRoutes } from 'react-router-dom';

import { Tabs, type TabsProps } from 'antd';

import { i18n } from 'i18n';
import { NotFound } from 'pages/NotFound';
import { EMainRoutes } from 'shared/typings';
import { Page, PageTitle } from 'shared/ui';
import { CapReportsList, RawReportsList } from 'widgets/ReportsList';

const reportsRoutes = [
	{
		path: `/`,
		element: <RawReportsList />,
	},
	{
		path: `/${EMainRoutes.REPORTS_CAP}`,
		element: <CapReportsList />,
	},
	{ element: <NotFound />, path: '/*' },
];

const reportTabs: TabsProps['items'] = [
	{
		key: `/${EMainRoutes.REPORTS}`,
		label: <NavLink to={`/${EMainRoutes.REPORTS}`}>{i18n.t('Raw Data')}</NavLink>,
	},
	{
		key: `/${EMainRoutes.REPORTS}/${EMainRoutes.REPORTS_CAP}`,
		label: <NavLink to={`/${EMainRoutes.REPORTS}/${EMainRoutes.REPORTS_CAP}`}>{i18n.t('Cap limits')}</NavLink>,
	},
];

interface IReportsProps extends HTMLAttributes<HTMLDivElement> {}

export const Reports: FC<IReportsProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { pathname } = useLocation();

	return (
		<Page {...props}>
			<PageTitle>{t('Reports')}</PageTitle>
			<div>
				<Tabs items={reportTabs} activeKey={pathname} size={'large'} />
				{useRoutes(reportsRoutes)}
			</div>
		</Page>
	);
};

export default Reports;
