import { FC, HTMLAttributes } from 'react';

import { Button } from 'antd';
import cn from 'classnames';

import ExportIcon from 'assets/images/icons/export.svg?react';
import { ReportsMainFilters, ReportsPeriodFilters } from 'features/Filters';
import { Table } from 'shared/ui';
import { useCapReportsList } from 'widgets/ReportsList/hooks/useCapReportsList.tsx';

import styles from './CapReportsList.module.scss';

interface ICapReportsListProps extends HTMLAttributes<HTMLDivElement> {}

export const CapReportsList: FC<ICapReportsListProps> = ({ className, ...props }) => {
	const { columns, data, exportURL, isDesktop, isError, isFetching, isLoading, t } = useCapReportsList();

	return (
		<div {...props} className={cn(className, styles.capReportsList)}>
			<div className={styles.capReportsList__filters}>
				<ReportsMainFilters />
				{isDesktop && (
					<Button href={exportURL} download icon={<ExportIcon />} iconPosition={'end'} size={'large'} type={'primary'}>
						{t('Export')}
					</Button>
				)}
			</div>

			<div className={styles.capReportsList__topbar}>
				<ReportsPeriodFilters />
				{!isDesktop && (
					<Button href={exportURL} download icon={<ExportIcon />} iconPosition={'end'} size={'middle'} type={'primary'}>
						{t('Export')}
					</Button>
				)}
			</div>
			<Table
				columns={columns}
				dataCount={data?.count}
				dataSource={isError ? [] : data?.results}
				isFirstLoading={isLoading}
				loading={isFetching}
				rowKey={(record) => `${record.offer?.uuid}${record.source_id}${record.month}`}
			/>
		</div>
	);
};
