import { FC, HTMLAttributes } from 'react';

import { Button } from 'antd';
import cn from 'classnames';

import ExportIcon from 'assets/images/icons/export.svg?react';
import { ReportsMainFilters, ReportsPeriodFilters } from 'features/Filters';
import { Table } from 'shared/ui';
import { useRawReportsList } from 'widgets/ReportsList/hooks/useRawReportsList';

import styles from './RawReportsList.module.scss';

interface IRawReportsListProps extends HTMLAttributes<HTMLDivElement> {}

export const RawReportsList: FC<IRawReportsListProps> = ({ className, ...props }) => {
	const { columns, data, exportURL, isDesktop, isError, isFetching, isLoading, t } = useRawReportsList();

	return (
		<div {...props} className={cn(className, styles.rawReportsList)}>
			<div className={styles.rawReportsList__filters}>
				<ReportsMainFilters />
				{isDesktop && (
					<Button href={exportURL} download icon={<ExportIcon />} iconPosition={'end'} size={'large'} type={'primary'}>
						{t('Export')}
					</Button>
				)}
			</div>

			<div className={styles.rawReportsList__topbar}>
				<ReportsPeriodFilters />
				{!isDesktop && (
					<Button href={exportURL} download icon={<ExportIcon />} iconPosition={'end'} size={'middle'} type={'primary'}>
						{t('Export')}
					</Button>
				)}
			</div>

			<Table
				columns={columns}
				dataCount={data?.count}
				dataSource={isError ? [] : data?.results}
				isFirstLoading={isLoading}
				loading={isFetching}
				rowKey={(record) => `${record.created_at}${record.amount}`}
			/>
		</div>
	);
};
